<?php require_once '../config/config.php';$title='Contact Us';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$v=[];foreach(['first_name','last_name','email','subject','enquiry_type','message'] as $f)$v[$f]=trim($_POST[$f]??'');if(!$v['first_name']||!$v['last_name']||!filter_var($v['email'],FILTER_VALIDATE_EMAIL)||!$v['subject']||!$v['message'])flash('danger','Please complete all required fields.');else{$s=db()->prepare("INSERT INTO contact_messages(first_name,last_name,email,subject,enquiry_type,message) VALUES(?,?,?,?,?,?)");$s->execute(array_values($v));flash('success','Your message has been received.');header('Location:contact.php');exit;}}require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Get in touch</span><h1 class="fw-bold">Contact FoodFusion</h1></div></div><section class="section"><div class="container"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php foreach(['first_name'=>'First Name','last_name'=>'Last Name','email'=>'Email','subject'=>'Subject'] as $n=>$lab):?><div class="col-md-6"><label class="form-label"><?=$lab?></label><input class="form-control" name="<?=$n?>" <?=$n==='email'?'type="email"':''?> required></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Enquiry Type</label><select class="form-select" name="enquiry_type"><?php foreach(['General Enquiry','Recipe Request','Technical Support','Partnership','Feedback','Other'] as $x):?><option><?=$x?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Message</label><textarea class="form-control" name="message" rows="7" required></textarea></div><button class="btn btn-primary">Send message</button></form></div></section><?php require '../includes/footer.php';?>